  const categorySlug = parts[0];
  const subSlug = parts[1];
  const pageTitleBase = formatSlugToTitle(subSlug);

  let category = 'Real Estate Intelligence';
  let kicker = 'Market Intelligence';
  let readTime = '5 min read';
  let h1 = `${pageTitleBase}: Lodha Altero Wakad`;
